const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define New Mexico geometry
  const newMexico = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'New Mexico'))
    .geometry();

  // 2. Function to get mean LST for a specific July
  function getJulyLST(year) {
    const startDate = ee.Date.fromYMD(year, 7, 1);
    const endDate = ee.Date.fromYMD(year, 7, 31);

    const col = ee.ImageCollection('MODIS/006/MOD11A1')
      .filterDate(startDate, endDate)
      .filterBounds(newMexico)
      .select('LST_Day_1km');

    return col;
  }

  // 3. Collect LST data for all Julys from 2000-2016
  const years = [];
  const lstValues = [];

  for (let year = 2000; year <= 2016; year++) {
    const col = getJulyLST(year);
    const size = col.size().getInfo();

    if (size === 0) {
      console.log(`Year ${year}: No images`);
      console.log("<answer>C1</answer>");
      return;
    }

    // Calculate mean LST (convert from Kelvin*0.02 to Celsius)
    const meanImg = col.mean();
    const stats = meanImg.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: newMexico,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const lstKelvin = stats['LST_Day_1km_mean'];
    const count = stats['LST_Day_1km_count'];

    if (!count || count === 0) {
      console.log(`Year ${year}: No valid pixels`);
      console.log("<answer>C2</answer>");
      return;
    }

    if (!lstKelvin || lstKelvin < 200 || lstKelvin > 400) {
      console.log(`Year ${year}: Invalid LST value`);
      console.log("<answer>C3</answer>");
      return;
    }

    const lstCelsius = lstKelvin * 0.02 - 273.15;
    years.push(year);
    lstValues.push(lstCelsius);

    console.log(`${year}: ${lstCelsius.toFixed(2)}°C (${size} imgs, ${count.toFixed(0)} px)`);
  }

  // 4. Find the year with maximum LST
  const july2016LST = lstValues[lstValues.length - 1];
  const maxLST = Math.max(...lstValues);
  const maxYear = years[lstValues.indexOf(maxLST)];

  console.log(`\nJuly 2016: ${july2016LST.toFixed(2)}°C`);
  console.log(`Maximum: ${maxLST.toFixed(2)}°C in ${maxYear}`);

  // 5. Determine answer
  if (july2016LST === maxLST) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
